#!/usr/bin/env python3
"""Write, or with --check compare, the generated crate list in THIRD_PARTY_NOTICES.md.

The list holds every crate that the db-sync-alt binary is built from: the
normal (not build- or dev-only) dependencies of the `db-sync-alt` package for
x86_64-unknown-linux-gnu, as `cargo metadata` resolves them from Cargo.lock.
"""
import argparse
from collections import Counter
import json
from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[2]
NOTICES = ROOT/'THIRD_PARTY_NOTICES.md'
BEGIN = '<!-- BEGIN generated by .github/scripts/third_party_notices.py -->'
END = '<!-- END generated -->'
BINARY = 'db-sync-alt'
TARGET = 'x86_64-unknown-linux-gnu'


def crates(metadata):
    packages = {p['id']: p for p in metadata['packages']}
    nodes = {n['id']: n for n in metadata['resolve']['nodes']}
    root = next(p['id'] for p in metadata['packages'] if p['name'] == BINARY and p['source'] is None)
    seen, stack = set(), [root]
    while stack:
        current = stack.pop()
        if current in seen:
            continue
        seen.add(current)
        stack.extend(d['pkg'] for d in nodes[current]['deps']
                     if any(kind['kind'] is None for kind in d['dep_kinds']))
    external = [packages[i] for i in seen if packages[i]['source'] is not None]
    missing = sorted(p['name'] for p in external if not p['license'])
    if missing:
        raise SystemExit('crates without a license expression: '+', '.join(missing))
    return sorted(external, key=lambda p: (p['name'], p['version']))


def section(external):
    lines = [BEGIN, '',
             f'{len(external)} crates, the normal dependencies of `{BINARY}` for `{TARGET}`',
             'as resolved from `Cargo.lock`. The license text of each crate is in its',
             'source package on crates.io.', '',
             '| License expression | Crates |', '| --- | --- |']
    for expression, count in sorted(Counter(p['license'] for p in external).items(),
                                    key=lambda item: (-item[1], item[0])):
        lines.append(f'| `{expression}` | {count} |')
    lines += ['', '| Crate | Version | License expression |', '| --- | --- | --- |']
    lines += [f"| {p['name']} | {p['version']} | `{p['license']}` |" for p in external]
    lines += ['', END]
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='fail if the file is not current')
    parser.add_argument('--metadata', type=Path, help='read `cargo metadata` output from this file')
    args = parser.parse_args()
    if args.metadata:
        metadata = json.loads(args.metadata.read_text())
    else:
        metadata = json.loads(subprocess.check_output(
            ['cargo', 'metadata', '--format-version', '1', '--locked', '--filter-platform', TARGET],
            cwd=ROOT))
    text = NOTICES.read_text()
    start, end = text.find(BEGIN), text.find(END)
    if start < 0 or end < start:
        raise SystemExit('THIRD_PARTY_NOTICES.md lacks the generated-section markers')
    updated = text[:start]+section(crates(metadata))+text[end+len(END):]
    if args.check:
        if updated != text:
            print('THIRD_PARTY_NOTICES.md is not current; run python3 .github/scripts/third_party_notices.py')
            return 1
        print('THIRD_PARTY_NOTICES.md lists the current crates.')
        return 0
    NOTICES.write_text(updated)
    print('THIRD_PARTY_NOTICES.md updated.')
    return 0


if __name__ == '__main__':
    sys.exit(main())
